head.b:skin:
:root{
  --sage:#8A9A7E; --sage-dark:#5F6F52; --sage-light:#B9C4AE;
  --cream:#FAF6EC; --cream-dark:#F0E9D8;
  --text:#3A3F35; --muted:#6E7768; --white:#FFFFFF;
  --danger:#C0524A; --accent:#D4A574; --accent-dark:#B8894F;
  --gold:#E8B923; --silver:#B8B8B8; --bronze:#CD7F32;
  --radius:14px; --card-shadow:0 2px 10px rgba(0,0,0,.04);
  --shadow-lg:0 12px 40px rgba(0,0,0,.12);
}
body.dark-mode{
  --cream:#1A1E1A; --cream-dark:#232823; --white:#2A2F2A;
  --text:#E8EBE4; --muted:#A8B0A0; --sage-light:#4A5444;
  --card-shadow:0 2px 10px rgba(0,0,0,.3);
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;background:var(--cream);color:var(--text);font-family:'Tajawal',sans-serif;line-height:1.7;transition:background .3s,color .3s;font-display:swap;-webkit-font-smoothing:antialiased;}
a{color:var(--sage-dark);text-decoration:none;}
body.dark-mode a{color:var(--sage-light);}
a:hover{text-decoration:underline;}
img{max-width:100%;height:auto;display:block;}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);}
.skip-link{position:absolute;top:-40px;right:0;background:var(--sage-dark);color:#fff;padding:8px 16px;z-index:10000;transition:top .3s;}
.skip-link:focus{top:0;}

/* NAVBAR */
.navbar{background:var(--white);box-shadow:0 2px 8px rgba(0,0,0,0.06);position:sticky;top:0;z-index:100;padding:0 16px;min-height:60px;}
.navbar-inner{max-width:1200px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;height:60px;gap:12px;}
.nav-logo{font-weight:900;font-size:18px;color:var(--sage-dark) !important;text-decoration:none;white-space:nowrap;}
.nav-links{display:flex;gap:14px;flex-wrap:wrap;}
.nav-links a{font-size:13px;font-weight:500;color:var(--text);text-decoration:none;transition:color 0.2s;cursor:pointer;white-space:nowrap;}
.nav-links a:hover{color:var(--sage-dark);}
.nav-links a.active{color:var(--sage-dark);font-weight:700;}

/* HEADER */
.header-inner{background:linear-gradient(135deg,var(--sage) 0%,var(--sage-dark) 100%);color:var(--white);padding:44px 16px 60px;text-align:center;position:relative;overflow:hidden;}
.header-inner::after{content:'';position:absolute;bottom:-40px;left:-40px;width:180px;height:180px;border-radius:50%;background:rgba(255,255,255,.08);}
.header-inner::before{content:'';position:absolute;top:-60px;right:-60px;width:220px;height:220px;border-radius:50%;background:rgba(255,255,255,.06);}
.blog-title a{color:var(--white);font-size:34px;font-weight:900;position:relative;z-index:1;}
.blog-desc{margin-top:10px;font-size:15px;color:var(--cream);position:relative;z-index:1;opacity:.95;}
.header-tools{position:absolute;top:16px;left:16px;display:flex;gap:8px;z-index:2;}
.header-tools button{background:rgba(255,255,255,.18);border:none;color:var(--white);width:40px;height:40px;border-radius:50%;cursor:pointer;font-size:17px;display:flex;align-items:center;justify-content:center;transition:all .2s;backdrop-filter:blur(10px);}
.header-tools button:hover{background:rgba(255,255,255,.35);transform:scale(1.1);}

/* MAIN */
.main-container{max-width:1100px;margin:-40px auto 30px;position:relative;z-index:2;padding:0 16px;}
.tabs{display:flex;gap:6px;background:var(--white);border-radius:var(--radius) var(--radius) 0 0;padding:8px;box-shadow:var(--shadow-lg);flex-wrap:wrap;min-height:60px;}
.tab-btn{flex:1;min-width:90px;padding:12px 14px;border:none;background:transparent;color:var(--muted);font-family:inherit;font-size:13px;font-weight:700;border-radius:10px;cursor:pointer;transition:all .2s;display:flex;align-items:center;justify-content:center;gap:6px;}
.tab-btn:hover{background:var(--cream);}
.tab-btn.active{background:var(--sage);color:var(--white);box-shadow:0 4px 12px rgba(138,154,126,.3);}
.tab-content{display:none;}
.tab-content.active{display:block;animation:fadeIn .3s ease;}
@keyframes fadeIn{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:translateY(0);}}
.translator-box{background:var(--white);border-radius:0 0 var(--radius) var(--radius);box-shadow:var(--shadow-lg);padding:24px;}

/* TEXT TRANSLATOR */
.t-row{display:flex;gap:14px;flex-wrap:wrap;align-items:flex-start;}
.t-col{flex:1;min-width:260px;}
.t-select{width:100%;padding:10px;border-radius:10px;border:1px solid var(--sage-light);font-family:inherit;background:var(--cream);margin-bottom:8px;color:var(--text);cursor:pointer;font-size:14px;}
.t-textarea{width:100%;min-height:130px;padding:14px;border-radius:10px;border:1px solid var(--sage-light);font-family:inherit;font-size:15px;resize:vertical;background:var(--cream);color:var(--text);transition:border-color .2s;}
.t-textarea:focus{outline:none;border-color:var(--sage);}
.t-tools{display:flex;justify-content:space-between;align-items:center;margin-top:8px;font-size:12px;color:var(--muted);flex-wrap:wrap;gap:6px;}
.t-tools > span:last-child{display:flex;gap:4px;flex-wrap:wrap;}
.t-tools button{background:none;border:1px solid var(--sage-light);border-radius:8px;padding:5px 10px;cursor:pointer;font-family:inherit;color:var(--sage-dark);font-size:12px;transition:all .2s;}
body.dark-mode .t-tools button{color:var(--text);}
.t-tools button:hover{background:var(--cream-dark);transform:translateY(-1px);}
.t-swap{align-self:center;background:var(--sage);color:var(--white);border:none;width:46px;height:46px;border-radius:50%;cursor:pointer;font-size:20px;margin-top:30px;transition:all .3s;box-shadow:0 4px 12px rgba(138,154,126,.3);}
.t-swap:hover{background:var(--sage-dark);transform:rotate(180deg);}
.t-actions{text-align:center;margin-top:18px;display:flex;gap:10px;justify-content:center;flex-wrap:wrap;}
.btn-main{background:var(--sage-dark);color:var(--white);border:none;padding:13px 36px;border-radius:30px;font-weight:700;font-family:inherit;cursor:pointer;font-size:15px;transition:all .2s;}
.btn-main:hover{background:var(--sage);transform:translateY(-2px);box-shadow:0 6px 18px rgba(138,154,126,.35);}
.btn-main:disabled{opacity:.6;cursor:not-allowed;transform:none;}
.btn-secondary{background:transparent;color:var(--sage-dark);border:1px solid var(--sage-light);padding:13px 24px;border-radius:30px;font-family:inherit;cursor:pointer;font-size:14px;transition:all .2s;}
body.dark-mode .btn-secondary{color:var(--text);}
.btn-secondary:hover{background:var(--cream-dark);}
.btn-accent{background:var(--accent);color:var(--white);border:none;padding:10px 20px;border-radius:24px;font-family:inherit;font-weight:700;cursor:pointer;font-size:13px;transition:all .2s;}
.btn-accent:hover{background:var(--accent-dark);transform:translateY(-2px);}
.t-status{text-align:center;font-size:13px;color:var(--muted);margin-top:10px;min-height:18px;}
.btn-speak{background:var(--sage) !important;color:var(--white) !important;border:none !important;font-weight:700 !important;padding:5px 14px !important;}
.btn-speak:hover{background:var(--sage-dark) !important;transform:scale(1.05);}
.btn-mic{background:var(--danger) !important;color:var(--white) !important;border:none !important;font-weight:700 !important;padding:5px 14px !important;}
.btn-mic.recording{animation:pulse 1s infinite;}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(192,82,74,.7);}50%{box-shadow:0 0 0 10px rgba(192,82,74,0);}}

.voice-panel{background:var(--cream);border-radius:10px;padding:14px;margin-top:14px;display:none;font-size:13px;border:1px solid var(--sage-light);}
.voice-panel.open{display:block;animation:fadeIn .25s ease;}
.voice-panel label{display:block;margin-bottom:6px;color:var(--muted);font-weight:500;}
.voice-panel select,.voice-panel input[type=range]{width:100%;padding:6px;border-radius:8px;border:1px solid var(--sage-light);background:var(--white);font-family:inherit;margin-bottom:10px;color:var(--text);}

/* OCR */
.ocr-zone{border:2px dashed var(--sage-light);border-radius:var(--radius);padding:30px 20px;text-align:center;transition:all .3s;background:var(--cream);cursor:pointer;}
.ocr-zone:hover{border-color:var(--sage);background:var(--cream-dark);}
.ocr-zone.dragover{border-color:var(--sage-dark);background:var(--cream-dark);}
.ocr-icon{font-size:56px;margin-bottom:12px;display:block;}
.ocr-title{font-size:18px;font-weight:700;color:var(--text);margin-bottom:6px;}
.ocr-sub{font-size:13px;color:var(--muted);margin-bottom:18px;}
.ocr-buttons{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;}
.ocr-buttons button{padding:12px 22px;border:none;border-radius:24px;font-family:inherit;font-weight:700;cursor:pointer;font-size:14px;transition:all .2s;display:flex;align-items:center;gap:6px;}
.btn-camera{background:var(--sage-dark);color:var(--white);}
.btn-camera:hover{background:var(--sage);transform:translateY(-2px);}
.btn-upload{background:var(--accent);color:var(--white);}
.btn-upload:hover{background:var(--accent-dark);transform:translateY(-2px);}
#cameraArea,#previewArea{display:none;margin-top:20px;}
#cameraArea.open,#previewArea.open{display:block;animation:fadeIn .3s ease;}
.camera-frame{position:relative;border-radius:var(--radius);overflow:hidden;background:#000;box-shadow:var(--shadow-lg);aspect-ratio:16/9;}
#cameraStream{width:100%;height:100%;object-fit:cover;display:block;}
.camera-controls{display:flex;gap:10px;justify-content:center;margin-top:12px;flex-wrap:wrap;}
#previewImg{width:100%;max-height:400px;object-fit:contain;border-radius:var(--radius);box-shadow:var(--shadow-lg);background:#000;}
.ocr-lang-row{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap;}
.ocr-lang-row select{flex:1;min-width:140px;padding:10px;border-radius:10px;border:1px solid var(--sage-light);background:var(--cream);font-family:inherit;color:var(--text);}
.progress-bar{height:6px;background:var(--cream-dark);border-radius:3px;overflow:hidden;margin-top:14px;display:none;}
.progress-bar.open{display:block;}
.progress-bar-inner{height:100%;background:linear-gradient(90deg,var(--sage),var(--accent));border-radius:3px;width:0%;transition:width .3s ease;}

/* FLASHCARDS */
.flashcard-container{display:flex;flex-direction:column;align-items:center;gap:16px;padding:10px;}
.flashcard{width:100%;max-width:480px;height:260px;perspective:1000px;cursor:pointer;}
.flashcard-inner{position:relative;width:100%;height:100%;transition:transform .6s;transform-style:preserve-3d;}
.flashcard.flipped .flashcard-inner{transform:rotateY(180deg);}
.flashcard-face{position:absolute;inset:0;backface-visibility:hidden;border-radius:var(--radius);padding:24px;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:var(--shadow-lg);text-align:center;}
.flashcard-front{background:var(--white);color:var(--text);}
.flashcard-back{background:var(--sage-dark);color:var(--white);transform:rotateY(180deg);}
.flashcard-front .fc-label,.flashcard-back .fc-label{font-size:11px;opacity:.7;margin-bottom:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;}
.flashcard-front .fc-text{font-size:24px;font-weight:700;line-height:1.5;}
.flashcard-back .fc-text{font-size:22px;font-weight:500;line-height:1.6;}
.flashcard-hint{font-size:12px;color:var(--muted);margin-top:8px;}
.flashcard-controls{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;}
.flashcard-controls button{padding:10px 20px;border-radius:24px;border:none;font-family:inherit;font-weight:700;cursor:pointer;font-size:14px;transition:all .2s;}
.btn-fc-primary{background:var(--sage-dark);color:var(--white);}
.btn-fc-primary:hover{background:var(--sage);}
.btn-fc-secondary{background:var(--cream-dark);color:var(--text);}
.btn-fc-secondary:hover{background:var(--sage-light);}
.fc-input-area{width:100%;max-width:480px;display:flex;gap:8px;flex-wrap:wrap;}
.fc-input-area input,.fc-input-area select{flex:1;min-width:120px;padding:10px;border-radius:10px;border:1px solid var(--sage-light);background:var(--cream);font-family:inherit;color:var(--text);}

/* STATS */
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-top:20px;}
.stat-card{background:var(--cream);border-radius:12px;padding:16px;text-align:center;border:1px solid var(--sage-light);}
body.dark-mode .stat-card{background:var(--cream-dark);}
.stat-card .stat-icon{font-size:28px;margin-bottom:6px;display:block;}
.stat-card .stat-num{font-size:24px;font-weight:900;color:var(--sage-dark);display:block;}
body.dark-mode .stat-card .stat-num{color:var(--text);}
.stat-card .stat-lbl{font-size:12px;color:var(--muted);}

/* ACHIEVEMENTS */
.achievements-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-top:16px;}
.achievement{background:var(--cream);border-radius:12px;padding:14px;text-align:center;border:1px solid var(--sage-light);opacity:.4;transition:all .3s;}
.achievement.unlocked{opacity:1;background:linear-gradient(135deg,#FFF8E1,var(--cream));border-color:var(--gold);box-shadow:0 4px 12px rgba(232,185,35,.2);}
.achievement .ach-icon{font-size:32px;display:block;margin-bottom:6px;}
.achievement .ach-name{font-size:12px;font-weight:700;color:var(--text);}
.achievement .ach-desc{font-size:10px;color:var(--muted);margin-top:4px;}

/* DICTIONARY */
.dict-search{display:flex;gap:8px;margin-bottom:16px;}
.dict-search input{flex:1;padding:12px;border-radius:10px;border:1px solid var(--sage-light);background:var(--cream);font-family:inherit;font-size:15px;color:var(--text);}
.dict-search select{padding:12px;border-radius:10px;border:1px solid var(--sage-light);background:var(--cream);font-family:inherit;color:var(--text);}
.dict-result{background:var(--cream);border-radius:12px;padding:20px;border-right:4px solid var(--sage);}
body.dark-mode .dict-result{background:var(--cream-dark);}
.dict-word{font-size:24px;font-weight:900;color:var(--sage-dark);margin-bottom:8px;}
body.dark-mode .dict-word{color:var(--text);}
.dict-meaning{font-size:16px;margin-bottom:12px;padding:12px;background:var(--white);border-radius:8px;}
.dict-example{font-size:14px;color:var(--muted);font-style:italic;padding:8px 12px;background:var(--white);border-radius:8px;margin-top:8px;border-right:3px solid var(--accent);}
.dict-example-label{font-size:11px;color:var(--muted);font-weight:700;display:block;margin-bottom:4px;}

/* QUIZ */
.quiz-modal{position:fixed;inset:0;background:rgba(0,0,0,.6);display:none;align-items:center;justify-content:center;z-index:10000;padding:16px;backdrop-filter:blur(4px);}
.quiz-modal.open{display:flex;animation:quizFadeIn .25s ease;}
@keyframes quizFadeIn{from{opacity:0;}to{opacity:1;}}
.quiz-content{background:var(--white);border-radius:var(--radius);box-shadow:0 20px 60px rgba(0,0,0,.3);width:100%;max-width:520px;max-height:90vh;overflow-y:auto;padding:24px;animation:quizSlideUp .3s ease;}
@keyframes quizSlideUp{from{transform:translateY(30px);opacity:0;}to{transform:translateY(0);opacity:1;}}
.quiz-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;}
.quiz-progress-text{font-weight:700;color:var(--sage-dark);font-size:14px;}
body.dark-mode .quiz-progress-text{color:var(--text);}
.quiz-close{background:none;border:none;font-size:22px;cursor:pointer;color:var(--muted);padding:0 6px;line-height:1;}
.quiz-close:hover{color:var(--danger);}
.quiz-progress{height:6px;background:var(--cream-dark);border-radius:3px;overflow:hidden;margin-bottom:24px;}
.quiz-progress-fill{height:100%;width:0%;background:linear-gradient(90deg,var(--sage),var(--accent));border-radius:3px;transition:width .4s ease;}
.quiz-body{text-align:center;}
.quiz-question{font-size:14px;color:var(--muted);margin-bottom:12px;}
.quiz-word{font-size:28px;font-weight:900;color:var(--text);margin-bottom:24px;line-height:1.4;padding:16px;background:var(--cream);border-radius:var(--radius);word-wrap:break-word;}
body.dark-mode .quiz-word{background:var(--cream-dark);}
.quiz-options{display:flex;flex-direction:column;gap:10px;margin-bottom:20px;text-align:right;}
.quiz-option{padding:14px 18px;border:2px solid var(--sage-light);border-radius:12px;background:var(--white);cursor:pointer;font-family:inherit;font-size:15px;color:var(--text);text-align:right;transition:all .2s;font-weight:500;}
.quiz-option:hover:not(:disabled){border-color:var(--sage);background:var(--cream);transform:translateX(-4px);}
.quiz-option.correct{border-color:#4CAF50 !important;background:#E8F5E9 !important;color:#2E7D32 !important;}
.quiz-option.wrong{border-color:var(--danger) !important;background:#FFEBEE !important;color:var(--danger) !important;}
.quiz-option:disabled{cursor:not-allowed;opacity:.85;}
.quiz-input{width:100%;padding:14px;border-radius:12px;border:2px solid var(--sage-light);background:var(--cream);font-family:inherit;font-size:16px;text-align:center;color:var(--text);margin-bottom:16px;}
.quiz-input:focus{outline:none;border-color:var(--sage);}
.quiz-feedback{padding:12px;border-radius:10px;font-size:14px;font-weight:700;margin-bottom:16px;}
.quiz-feedback.correct{background:#E8F5E9;color:#2E7D32;border-right:4px solid #4CAF50;}
.quiz-feedback.wrong{background:#FFEBEE;color:var(--danger);border-right:4px solid var(--danger);}
.quiz-footer{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;}
.quiz-result{text-align:center;}
.result-icon{font-size:64px;margin-bottom:12px;}
.result-title{font-size:26px;font-weight:900;color:var(--sage-dark);margin:0 0 6px;}
.result-subtitle{color:var(--muted);font-size:14px;margin:0 0 24px;}
.score-circle{width:140px;height:140px;margin:0 auto;border-radius:50%;background:conic-gradient(var(--sage) var(--score-deg,0deg),var(--cream-dark) 0deg);display:flex;align-items:center;justify-content:center;position:relative;}
.score-circle::before{content:'';position:absolute;inset:10px;background:var(--white);border-radius:50%;}
.score-number{position:relative;z-index:1;font-size:44px;font-weight:900;color:var(--sage-dark);}
.score-percent{position:relative;z-index:1;font-size:20px;font-weight:700;color:var(--muted);align-self:flex-start;margin-top:20px;}
.result-stats{display:flex;justify-content:space-around;gap:10px;margin:24px 0;flex-wrap:wrap;}
.stat-item{flex:1;min-width:90px;background:var(--cream);border-radius:12px;padding:14px 8px;}
.stat-value{display:block;font-size:22px;font-weight:900;color:var(--sage-dark);margin-bottom:4px;}
.stat-label{font-size:12px;color:var(--muted);}
.result-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:24px;}
.difficulty-picker{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:16px;}
.diff-btn{padding:12px 24px;border:2px solid var(--sage-light);border-radius:24px;background:var(--white);color:var(--text);font-family:inherit;font-weight:700;cursor:pointer;font-size:14px;transition:all .2s;}
.diff-btn:hover{border-color:var(--sage);transform:translateY(-2px);}
.diff-btn.active{background:var(--sage-dark);color:var(--white);border-color:var(--sage-dark);}

/* MODALS */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.75);display:none;align-items:center;justify-content:center;z-index:100000;padding:20px;backdrop-filter:blur(8px);}
.modal-overlay.open{display:flex;animation:modalFadeIn .3s ease;}
@keyframes modalFadeIn{from{opacity:0;}to{opacity:1;}}
.modal-content{background:#FAF6EC;border-radius:14px;box-shadow:0 25px 80px rgba(0,0,0,.4);width:100%;max-width:850px;max-height:90vh;overflow:hidden;position:relative;animation:modalSlideUp .4s ease;}
body.dark-mode .modal-content{background:#1A1E1A;}
@keyframes modalSlideUp{from{transform:translateY(40px);opacity:0;}to{transform:translateY(0);opacity:1;}}
.modal-close{position:absolute;top:12px;left:12px;z-index:10;background:rgba(192,82,74,.9);color:#fff;border:none;width:40px;height:40px;border-radius:50%;cursor:pointer;font-size:20px;font-weight:700;display:flex;align-items:center;justify-content:center;transition:all .2s;box-shadow:0 4px 12px rgba(0,0,0,.2);}
.modal-close:hover{background:#C0524A;transform:scale(1.1) rotate(90deg);}
.modal-body{padding:40px 30px 30px;overflow-y:auto;max-height:90vh;font-family:'Tajawal',sans-serif;line-height:1.9;color:#3A3F35;}
body.dark-mode .modal-body{color:#E8EBE4;}
.modal-body h1{margin-top:0;}
.modal-body h2{color:#5F6F52;}
body.dark-mode .modal-body h2{color:#B9C4AE;}
.modal-body a{color:#5F6F52;}
.modal-body table{background:#fff;border-radius:8px;overflow:hidden;}
.modal-body table td,.modal-body table th{color:#3A3F35;}

.history-box{background:var(--white);border-radius:var(--radius);box-shadow:var(--card-shadow);padding:18px;margin-top:18px;}
.history-box h3{margin-top:0;color:var(--sage-dark);font-size:15px;display:flex;justify-content:space-between;align-items:center;}
.history-box h3 button{background:none;border:1px solid var(--sage-light);border-radius:8px;padding:4px 10px;font-size:11px;cursor:pointer;color:var(--muted);font-family:inherit;}
.history-item{padding:9px 0;border-bottom:1px solid var(--cream-dark);font-size:13px;display:flex;justify-content:space-between;gap:10px;}
.history-item:last-child{border-bottom:none;}
.history-item .h-src{color:var(--muted);font-size:11px;white-space:nowrap;font-weight:700;}
.history-item .h-text{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}

/* LAYOUT */
.layout{max-width:1100px;margin:0 auto;display:flex;gap:24px;padding:40px 16px;flex-wrap:wrap;}
.main-col{flex:3;min-width:280px;}
.sidebar-col{flex:1;min-width:240px;}

.post-card{background:var(--white);border-radius:var(--radius);padding:20px;margin-bottom:18px;box-shadow:var(--card-shadow);transition:transform .2s;}
.post-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg);}
.post-title a{font-size:20px;font-weight:700;color:var(--text);}
.post-title a:hover{color:var(--sage-dark);}
.post-meta{font-size:12px;color:var(--muted);margin:6px 0;}
.post-snippet{font-size:15px;color:var(--text);}
.read-more{font-weight:700;font-size:13px;display:inline-block;margin-top:8px;}
.post-full{background:var(--white);border-radius:var(--radius);padding:24px;box-shadow:var(--card-shadow);margin-bottom:18px;}
.post-full h1{font-size:26px;margin-top:0;color:var(--text);}
.post-body{font-size:16px;line-height:1.9;}
.post-body img{border-radius:10px;margin:10px 0;}

.pager{display:flex;justify-content:space-between;margin-top:20px;gap:10px;}
.pager a{background:var(--sage);color:var(--white);padding:8px 18px;border-radius:20px;}
.pager a:hover{background:var(--sage-dark);text-decoration:none;}

/* ARTICLES SECTION */
.articles-section{max-width:1100px;margin:40px auto;padding:0 16px;}
.articles-header{text-align:center;margin-bottom:24px;}
.articles-header h2{font-size:28px;color:var(--sage-dark);margin:0 0 8px;}
.articles-header p{color:var(--muted);font-size:14px;margin:0;}
.articles-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:18px;}
.article-card{background:var(--white);border-radius:var(--radius);overflow:hidden;box-shadow:var(--card-shadow);transition:transform .2s;display:flex;flex-direction:column;}
.article-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);}
.article-cover{height:160px;background:linear-gradient(135deg,var(--sage),var(--sage-dark));display:flex;align-items:center;justify-content:center;font-size:56px;}
.article-body{padding:18px;flex:1;display:flex;flex-direction:column;}
.article-cat{font-size:11px;color:var(--accent-dark);font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;}
.article-title{font-size:17px;font-weight:700;color:var(--text);margin:0 0 8px;line-height:1.4;}
.article-excerpt{font-size:13px;color:var(--muted);flex:1;margin-bottom:12px;line-height:1.6;}
.article-meta{font-size:11px;color:var(--muted);display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--cream-dark);padding-top:10px;}

.widget-box{background:var(--white);border-radius:var(--radius);padding:18px;margin-bottom:18px;box-shadow:var(--card-shadow);}
.widget-box h3{margin-top:0;color:var(--sage-dark);font-size:16px;border-bottom:2px solid var(--cream-dark);padding-bottom:8px;}
.label-cloud a{display:inline-block;background:var(--cream-dark);padding:5px 12px;border-radius:16px;margin:3px;font-size:12px;color:var(--text);}
.popular-posts{list-style:none;padding:0;margin:0;}
.popular-posts li{padding:7px 0;border-bottom:1px solid var(--cream-dark);font-size:14px;}
.popular-posts li:last-child{border-bottom:none;}

.comments-box{background:var(--white);border-radius:var(--radius);padding:20px;box-shadow:var(--card-shadow);margin-bottom:18px;}

/* SUPPORT */
.support-box{background:linear-gradient(135deg,var(--accent) 0%,var(--accent-dark) 100%);color:#fff;padding:20px;border-radius:var(--radius);text-align:center;margin-bottom:18px;}
.support-box h3{margin:0 0 8px;font-size:17px;}
.support-box p{margin:0 0 12px;font-size:13px;opacity:.95;}
.support-box a{background:rgba(255,255,255,.25);color:#fff;padding:10px 20px;border-radius:24px;text-decoration:none;font-weight:700;font-size:13px;display:inline-block;backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.3);}
.support-box a:hover{background:rgba(255,255,255,.4);text-decoration:none;}

.pro-box{background:linear-gradient(135deg,#E8B923 0%,#B8894F 100%);color:#fff;padding:20px;border-radius:var(--radius);text-align:center;margin-bottom:18px;}
.pro-box h3{margin:0 0 8px;font-size:17px;}
.pro-box p{margin:0 0 12px;font-size:13px;opacity:.95;}
.pro-box a{background:#fff;color:#5F6F52;padding:10px 20px;border-radius:24px;text-decoration:none;font-weight:700;font-size:13px;display:inline-block;}
.pro-box a:hover{transform:scale(1.05);text-decoration:none;}

/* FOOTER */
.footer-inner{text-align:center;padding:22px 16px;background:var(--sage-dark);color:var(--cream);font-size:13px;}
.footer-inner a{color:var(--cream);cursor:pointer;text-decoration:underline;}

/* TOAST */
.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%) translateY(20px);background:var(--sage-dark);color:var(--white);padding:12px 24px;border-radius:28px;font-size:13px;opacity:0;pointer-events:none;transition:all .3s;z-index:99999;box-shadow:var(--shadow-lg);max-width:90%;text-align:center;}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0);}

/* ACHIEVEMENT POPUP */
.achievement-popup{position:fixed;top:80px;left:50%;transform:translateX(-50%) translateY(-100px);background:linear-gradient(135deg,#FFF8E1,#FAF6EC);border:2px solid var(--gold);border-radius:16px;padding:16px 24px;box-shadow:0 12px 40px rgba(232,185,35,.4);z-index:99999;display:flex;align-items:center;gap:14px;transition:transform .5s cubic-bezier(.68,-.55,.27,1.55);}
.achievement-popup.show{transform:translateX(-50%) translateY(0);}
.achievement-popup .ap-icon{font-size:40px;}
.achievement-popup .ap-info h4{margin:0 0 2px;color:#5F6F52;font-size:15px;}
.achievement-popup .ap-info p{margin:0;color:#6E7768;font-size:12px;}

@media (max-width:640px){
  .navbar{padding:0 12px;}
  .navbar-inner{height:56px;}
  .nav-logo{font-size:15px;}
  .nav-links{display:none;}
  .blog-title a{font-size:24px;}
  .main-container{margin:-30px auto 20px;padding:0 10px;}
  .translator-box{padding:16px;}
  .t-swap{display:none;}
  .layout{padding:30px 12px;flex-direction:column;}
  .post-full{padding:16px;}
  .post-full h1{font-size:20px;}
  .post-card{padding:16px;border-radius:12px;}
  .t-actions{flex-direction:column;}
  .btn-main,.btn-secondary{width:100%;}
  .tab-btn{font-size:11px;padding:9px 6px;min-width:auto;}
  .tab-btn span:not(.icon){display:none;}
  .tab-btn .icon{font-size:18px;}
  .flashcard{height:220px;}
  .flashcard-front .fc-text{font-size:20px;}
  .flashcard-back .fc-text{font-size:18px;}
  .quiz-content{padding:18px;max-height:95vh;}
  .quiz-word{font-size:22px;}
  .score-circle{width:120px;height:120px;}
  .score-number{font-size:36px;}
  .result-actions{flex-direction:column;}
  .result-actions .btn-main,.result-actions .btn-secondary{width:100%;}
  .modal-body{padding:50px 16px 20px;}
  .modal-content{max-height:95vh;border-radius:12px;}
  .modal-close{top:8px;left:8px;width:36px;height:36px;font-size:18px;}
  .articles-grid{grid-template-columns:1fr;}
  .articles-header h2{font-size:22px;}
}

b:includable.script:
//
(function(){
  'use strict';

  var speechMap = {
    ar:'ar-SA', en:'en-US', ur:'ur-PK', hi:'hi-IN', bn:'bn-BD',
    id:'id-ID', tl:'fil-PH', fa:'fa-IR', tr:'tr-TR', fr:'fr-FR',
    es:'es-ES', de:'de-DE', ru:'ru-RU', zh:'zh-CN', ko:'ko-KR', ja:'ja-JP', it:'it-IT'
  };
  var ocrToSpeechMap = {
    'ara':'ar','eng':'en','urd':'ur','hin':'hi','ben':'bn','ind':'id',
    'fil':'tl','fas':'fa','tur':'tr','fra':'fr','spa':'es','deu':'de','rus':'ru',
    'chi_sim':'zh','kor':'ko','jpn':'ja','ita':'it'
  };

  var toast = document.getElementById('toast');
  function showToast(msg){
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(window._toastTimer);
    window._toastTimer = setTimeout(function(){ toast.classList.remove('show'); }, 2500);
  }
  function countWords(text){ return (!text || !text.trim()) ? 0 : text.trim().split(/\s+/).length; }
  function updateCount(el, targetId){
    var t = el.value || '';
    document.getElementById(targetId).textContent = t.length + ' حرف · ' + countWords(t) + ' كلمة';
  }

  // ============ PWA INSTALL ============
  var deferredPrompt = null;
  var installBtn = document.getElementById('installPWA');
  window.addEventListener('beforeinstallprompt', function(e){
    e.preventDefault();
    deferredPrompt = e;
    if(installBtn) installBtn.style.display = 'flex';
  });
  if(installBtn){
    installBtn.addEventListener('click', function(){
      if(deferredPrompt){
        deferredPrompt.prompt();
        deferredPrompt.userChoice.then(function(choice){
          if(choice.outcome === 'accepted'){ showToast('✅ تم تثبيت التطبيق'); }
          deferredPrompt = null;
          installBtn.style.display = 'none';
        });
      }
    });
  }
  if('serviceWorker' in navigator){
    window.addEventListener('load', function(){
      navigator.serviceWorker.register('/service-worker.js').catch(function(){});
    });
  }

  // ============ DARK MODE ============
  var themeToggle = document.getElementById('themeToggle');
  var isDark = localStorage.getItem('darkMode') === '1';
  if(isDark){ document.body.classList.add('dark-mode'); themeToggle.textContent = '☀️'; }
  themeToggle.addEventListener('click', function(){
    document.body.classList.toggle('dark-mode');
    var nowDark = document.body.classList.contains('dark-mode');
    localStorage.setItem('darkMode', nowDark ? '1' : '0');
    themeToggle.textContent = nowDark ? '☀️' : '🌙';
  });

  // ============ TABS ============
  var tabBtns = document.querySelectorAll('.tab-btn');
  var tabContents = document.querySelectorAll('.tab-content');
  tabBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      var tab = this.getAttribute('data-tab');
      tabBtns.forEach(function(b){ b.classList.remove('active'); b.setAttribute('aria-selected','false'); });
      tabContents.forEach(function(c){ c.classList.remove('active'); });
      this.classList.add('active');
      this.setAttribute('aria-selected','true');
      var target = document.querySelector('.tab-content[data-tab="' + tab + '"]');
      if(target) target.classList.add('active');
      if(tab === 'stats') renderStats();
      if(tab === 'dict') loadDailyWord();
    });
  });
  window.switchTab = function(tabName){
    tabBtns.forEach(function(b){ if(b.getAttribute('data-tab') === tabName) b.click(); });
    var mc = document.querySelector('.main-container');
    if(mc) mc.scrollIntoView({behavior:'smooth', block:'start'});
  };

  // ============ MODALS ============
  window.openModal = function(id){
    var m = document.getElementById(id);
    if(m){ m.classList.add('open'); document.body.style.overflow = 'hidden'; }
  };
  window.closeModal = function(id){
    var m = document.getElementById(id);
    if(m){ m.classList.remove('open'); document.body.style.overflow = ''; }
  };
  document.querySelectorAll('.modal-overlay').forEach(function(o){
    o.addEventListener('click', function(e){ if(e.target === o) closeModal(o.id); });
  });
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape'){
      document.querySelectorAll('.modal-overlay.open').forEach(function(m){ closeModal(m.id); });
    }
  });

  // ============ STATS SYSTEM ============
  function getStats(){
    try{ return JSON.parse(localStorage.getItem('userStats') || '{"translations":0,"wordsLearned":0,"quizzesTaken":0,"bestScore":0,"streakDays":0,"lastActive":"","totalPoints":0}'); }
    catch(e){ return {translations:0,wordsLearned:0,quizzesTaken:0,bestScore:0,streakDays:0,lastActive:"",totalPoints:0}; }
  }
  function saveStats(s){ localStorage.setItem('userStats', JSON.stringify(s)); }
  function updateStreak(){
    var s = getStats();
    var today = new Date().toDateString();
    if(s.lastActive !== today){
      var yesterday = new Date(Date.now() - 86400000).toDateString();
      s.streakDays = (s.lastActive === yesterday) ? (s.streakDays + 1) : 1;
      s.lastActive = today;
      saveStats(s);
    }
  }
  function addPoints(n){
    var s = getStats();
    s.totalPoints += n;
    saveStats(s);
    checkAchievements();
  }
  function renderStats(){
    var s = getStats();
    var grid = document.getElementById('statsGrid');
    grid.innerHTML = 
      '<div class="stat-card"><span class="stat-icon">📝</span><span class="stat-num">' + s.translations + '</span><span class="stat-lbl">ترجمة</span></div>' +
      '<div class="stat-card"><span class="stat-icon">🎴</span><span class="stat-num">' + s.wordsLearned + '</span><span class="stat-lbl">كلمة محفوظة</span></div>' +
      '<div class="stat-card"><span class="stat-icon">🎯</span><span class="stat-num">' + s.quizzesTaken + '</span><span class="stat-lbl">اختبار</span></div>' +
      '<div class="stat-card"><span class="stat-icon">🔥</span><span class="stat-num">' + s.streakDays + '</span><span class="stat-lbl">سلسلة أيام</span></div>' +
      '<div class="stat-card"><span class="stat-icon">🏆</span><span class="stat-num">' + s.bestScore + '%</span><span class="stat-lbl">أفضل نتيجة</span></div>' +
      '<div class="stat-card"><span class="stat-icon">⭐</span><span class="stat-num">' + s.totalPoints + '</span><span class="stat-lbl">نقطة</span></div>';
    renderAchievements();
  }
  function renderAchievements(){
    var s = getStats();
    var fc = (function(){ try{return JSON.parse(localStorage.getItem('flashcards')||'[]').length;}catch(e){return 0;} })();
    var achs = [
      {id:'first_trans', icon:'🌟', name:'البداية', desc:'أول ترجمة', check: s.translations >= 1},
      {id:'trans_10', icon:'📝', name:'مترجم', desc:'10 ترجمات', check: s.translations >= 10},
      {id:'trans_100', icon:'🎓', name:'محترف', desc:'100 ترجمة', check: s.translations >= 100},
      {id:'fc_5', icon:'📚', name:'متعلم', desc:'5 بطاقات', check: fc >= 5},
      {id:'fc_20', icon:'🧠', name:'حافظ', desc:'20 بطاقة', check: fc >= 20},
      {id:'quiz_1', icon:'🎯', name:'مختبر', desc:'اختبار واحد', check: s.quizzesTaken >= 1},
      {id:'quiz_perfect', icon:'💯', name:'مثالي', desc:'100% في اختبار', check: s.bestScore >= 100},
      {id:'streak_7', icon:'🔥', name:'ملتزم', desc:'7 أيام متتالية', check: s.streakDays >= 7},
      {id:'points_100', icon:'⭐', name:'نجم', desc:'100 نقطة', check: s.totalPoints >= 100}
    ];
    var grid = document.getElementById('achievementsGrid');
    grid.innerHTML = achs.map(function(a){
      return '<div class="achievement ' + (a.check ? 'unlocked' : '') + '"><span class="ach-icon">' + a.icon + '</span><div class="ach-name">' + a.name + '</div><div class="ach-desc">' + a.desc + '</div></div>';
    }).join('');
    var unlocked = achs.filter(function(a){ return a.check; }).map(function(a){ return a.id; });
    localStorage.setItem('unlockedAchievements', JSON.stringify(unlocked));
  }
  function checkAchievements(){
    var prev = [];
    try{ prev = JSON.parse(localStorage.getItem('unlockedAchievements') || '[]'); }catch(e){}
    var s = getStats();
    var fc = (function(){ try{return JSON.parse(localStorage.getItem('flashcards')||'[]').length;}catch(e){return 0;} })();
    var achs = [
      {id:'first_trans', icon:'🌟', name:'البداية', check: s.translations >= 1},
      {id:'trans_10', icon:'📝', name:'مترجم', check: s.translations >= 10},
      {id:'trans_100', icon:'🎓', name:'محترف', check: s.translations >= 100},
      {id:'fc_5', icon:'📚', name:'متعلم', check: fc >= 5},
      {id:'fc_20', icon:'🧠', name:'حافظ', check: fc >= 20},
      {id:'quiz_1', icon:'🎯', name:'مختبر', check: s.quizzesTaken >= 1},
      {id:'quiz_perfect', icon:'💯', name:'مثالي', check: s.bestScore >= 100},
      {id:'streak_7', icon:'🔥', name:'ملتزم', check: s.streakDays >= 7},
      {id:'points_100', icon:'⭐', name:'نجم', check: s.totalPoints >= 100}
    ];
    achs.forEach(function(a){
      if(a.check && prev.indexOf(a.id) === -1){
        showAchievementPopup(a.icon, 'إنجاز جديد: ' + a.name);
        prev.push(a.id);
      }
    });
    localStorage.setItem('unlockedAchievements', JSON.stringify(prev));
  }
  function showAchievementPopup(icon, title){
    var popup = document.getElementById('achievementPopup');
    document.getElementById('apIcon').textContent = icon;
    document.getElementById('apTitle').textContent = title;
    popup.classList.add('show');
    setTimeout(function(){ popup.classList.remove('show'); }, 4000);
  }
  window.resetStats = function(){
    if(!confirm('إعادة تعيين كل الإحصائيات؟')) return;
    localStorage.removeItem('userStats');
    localStorage.removeItem('unlockedAchievements');
    renderStats();
    showToast('تم إعادة التعيين');
  };
  updateStreak();

  // ============ VOICE INPUT (MIC) ============
  var recognition = null;
  var isRecording = false;
  var micBtn = document.getElementById('micBtn');
  if('webkitSpeechRecognition' in window || 'SpeechRecognition' in window){
    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    recognition = new SR();
    recognition.continuous = false;
    recognition.interimResults = false;
  } else {
    if(micBtn){ micBtn.style.display = 'none'; }
  }
  window.toggleMic = function(){
    if(!recognition){ showToast('⚠️ المتصفح لا يدعم الإدخال الصوتي'); return; }
    if(isRecording){ recognition.stop(); return; }
    var langCode = srcLang.value;
    recognition.lang = speechMap[langCode] || 'en-US';
    isRecording = true;
    micBtn.classList.add('recording');
    micBtn.textContent = '⏹️';
    showToast('🎤 جاري الاستماع...');
    recognition.start();
    recognition.onresult = function(e){
      var transcript = e.results[0][0].transcript;
      srcText.value = (srcText.value ? srcText.value + ' ' : '') + transcript;
      updateCount(srcText, 'srcCount');
      showToast('✅ تم التعرف: ' + transcript.substring(0,30));
    };
    recognition.onerror = function(e){ showToast('❌ خطأ: ' + e.error); };
    recognition.onend = function(){
      isRecording = false;
      micBtn.classList.remove('recording');
      micBtn.textContent = '🎤';
    };
  };

  // ============ TRANSLATION ============
  var srcText = document.getElementById('srcText');
  var tgtText = document.getElementById('tgtText');
  var srcLang = document.getElementById('srcLang');
  var tgtLang = document.getElementById('tgtLang');
  var status  = document.getElementById('tStatus');

  srcText.addEventListener('input', function(){ updateCount(srcText, 'srcCount'); });
  tgtText.addEventListener('input', function(){ updateCount(tgtText, 'tgtCount'); });

  document.getElementById('swapBtn').addEventListener('click', function(){
    var tl = srcLang.value; srcLang.value = tgtLang.value; tgtLang.value = tl;
    var tt = srcText.value; srcText.value = tgtText.value; tgtText.value = tt;
    updateCount(srcText, 'srcCount'); updateCount(tgtText, 'tgtCount');
  });

  window.clearText = function(id){
    var el = document.getElementById(id);
    el.value = '';
    var cntId = id === 'srcText' ? 'srcCount' : (id === 'tgtText' ? 'tgtCount' : 'ocrSrcCount');
    if(document.getElementById(cntId)) updateCount(el, cntId);
    el.focus();
  };
  window.clearAll = function(){
    srcText.value = ''; tgtText.value = '';
    updateCount(srcText, 'srcCount'); updateCount(tgtText, 'tgtCount');
    status.textContent = ''; showToast('تم مسح الكل');
  };
  window.pasteFromClipboard = function(){
    if(navigator.clipboard && navigator.clipboard.readText){
      navigator.clipboard.readText().then(function(text){
        srcText.value = text; updateCount(srcText, 'srcCount'); showToast('تم اللصق');
      }).catch(function(){ srcText.focus(); showToast('الصق يدوياً'); });
    } else { srcText.focus(); showToast('الصق يدوياً'); }
  };

  function translateGoogle(text, src, tgt){
    var url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=' + src + '&tl=' + tgt + '&dt=t&q=' + encodeURIComponent(text);
    return fetch(url).then(function(r){ return r.json(); }).then(function(data){
      if(data && data[0] && data[0][0] && data[0][0][0]){
        var result = '';
        for(var i = 0; i < data[0].length; i++){ if(data[0][i] && data[0][i][0]) result += data[0][i][0]; }
        return result;
      }
      throw new Error('no result');
    });
  }
  function translateMyMemory(text, src, tgt){
    var url = 'https://api.mymemory.translated.net/get?q=' + encodeURIComponent(text) + '&langpair=' + src + '|' + tgt;
    return fetch(url).then(function(r){ return r.json(); }).then(function(data){
      if(data && data.responseData && data.responseData.translatedText){ return data.responseData.translatedText; }
      throw new Error('no result');
    });
  }
  function translate(text, src, tgt){
    return translateGoogle(text, src, tgt).catch(function(){ return translateMyMemory(text, src, tgt); });
  }

  document.getElementById('translateBtn').addEventListener('click', function(){
    var text = srcText.value.trim();
    if(!text){ status.textContent = 'الرجاء كتابة نص.'; return; }
    var src = srcLang.value, tgt = tgtLang.value;
    if(src === tgt){ tgtText.value = text; updateCount(tgtText, 'tgtCount'); status.textContent = 'اللغتان متطابقتان.'; return; }
    status.textContent = '⏳ جاري الترجمة...';
    translate(text, src, tgt).then(function(result){
      tgtText.value = result;
      updateCount(tgtText, 'tgtCount');
      status.textContent = '✅ تمت الترجمة';
      saveHistory(src, tgt, text, result);
      var s = getStats(); s.translations++; saveStats(s); addPoints(1);
    }).catch(function(){ status.textContent = '❌ تعذرت الترجمة'; });
  });

  function getHistory(){ try{ return JSON.parse(localStorage.getItem('translateHistory') || '[]'); }catch(e){ return []; } }
  function saveHistory(src, tgt, srcT, tgtT){
    var h = getHistory();
    h.unshift({ src:src, tgt:tgt, srcT:srcT.substring(0,80), tgtT:tgtT.substring(0,80), time:Date.now() });
    h = h.slice(0, 10);
    localStorage.setItem('translateHistory', JSON.stringify(h));
    renderHistory();
  }
  function renderHistory(){
    var h = getHistory();
    var box = document.getElementById('historyBox');
    var list = document.getElementById('historyList');
    if(h.length === 0){ box.style.display = 'none'; return; }
    box.style.display = 'block';
    list.innerHTML = h.map(function(item){
      return '<div class="history-item"><span class="h-src">' + item.src + ' → ' + item.tgt + '</span><span class="h-text">' + item.tgtT + '</span></div>';
    }).join('');
  }
  window.clearHistory = function(){ localStorage.removeItem('translateHistory'); renderHistory(); showToast('تم مسح السجل'); };

  // ============ SPEECH SYNTHESIS ============
  var voices = [];
  var voiceSelect = document.getElementById('voiceSelect');
  var rateInput = document.getElementById('rateInput');
  var pitchInput = document.getElementById('pitchInput');

  function loadVoices(){
    if(!window.speechSynthesis) return;
    voices = window.speechSynthesis.getVoices();
    voiceSelect.innerHTML = '<option value="">تلقائي (حسب اللغة)</option>';
    voices.forEach(function(v, i){
      var opt = document.createElement('option');
      opt.value = i;
      var isAr = v.lang && v.lang.toLowerCase().indexOf('ar') === 0;
      opt.textContent = (isAr ? '⭐ ' : '') + v.name + ' (' + v.lang + ')';
      voiceSelect.appendChild(opt);
    });
  }
  if(window.speechSynthesis){
    loadVoices();
    window.speechSynthesis.onvoiceschanged = loadVoices;
    setTimeout(loadVoices, 500); setTimeout(loadVoices, 1500);
  }
  rateInput.addEventListener('input', function(){ document.getElementById('rateVal').textContent = this.value; });
  pitchInput.addEventListener('input', function(){ document.getElementById('pitchVal').textContent = this.value; });
  window.openVoicePanel = function(){ document.getElementById('voicePanel').classList.toggle('open'); };

  function findVoiceForLang(langCode){
    if(!voices || voices.length === 0) voices = window.speechSynthesis.getVoices();
    var targetLang = (speechMap[langCode] || 'en-US').toLowerCase();
    var targetPrefix = targetLang.split('-')[0];
    var found = null;
    for(var i = 0; i < voices.length; i++){ if((voices[i].lang || '').toLowerCase() === targetLang){ found = voices[i]; break; } }
    if(!found) for(var j = 0; j < voices.length; j++){ if((voices[j].lang || '').toLowerCase().split('-')[0] === targetPrefix){ found = voices[j]; break; } }
    return found;
  }

  window.speakText = function(textId, langIdOrCode){
    if(!window.speechSynthesis){ showToast('❌ لا يوجد دعم'); return; }
    var el = document.getElementById(textId);
    if(!el) return;
    var text = (el.value || '').trim();
    if(!text){ showToast('⚠️ لا يوجد نص'); return; }
    var langCode;
    if(document.getElementById(langIdOrCode)){ langCode = document.getElementById(langIdOrCode).value; }
    else if(ocrToSpeechMap[langIdOrCode]){ langCode = ocrToSpeechMap[langIdOrCode]; }
    else { langCode = langIdOrCode; }
    var utter = new SpeechSynthesisUtterance(text);
    utter.lang = speechMap[langCode] || 'en-US';
    utter.rate = parseFloat(rateInput.value) || 1;
    utter.pitch = parseFloat(pitchInput.value) || 1;
    var selectedIdx = voiceSelect.value;
    if(selectedIdx !== ''){
      var chosen = voices[parseInt(selectedIdx, 10)];
      if(chosen){ utter.voice = chosen; utter.lang = chosen.lang; }
    } else {
      var auto = findVoiceForLang(langCode);
      if(auto){ utter.voice = auto; utter.lang = auto.lang; }
    }
    window.speechSynthesis.cancel();
    setTimeout(function(){ window.speechSynthesis.speak(utter); showToast('🔊 جاري النطق...'); }, 100);
  };
  window.stopSpeech = function(){ if(window.speechSynthesis){ window.speechSynthesis.cancel(); showToast('⏹️ تم الإيقاف'); } };

  // ============ COPY / DOWNLOAD / SHARE ============
  window.copyText = function(textId){
    var el = document.getElementById(textId);
    var val = el.value;
    if(!val){ showToast('لا يوجد نص'); return; }
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(val).then(function(){ showToast('✅ تم النسخ'); });
    } else { el.select(); try{ document.execCommand('copy'); showToast('✅ تم النسخ'); }catch(e){} }
  };
  window.downloadText = function(){
    var val = tgtText.value;
    if(!val){ showToast('لا يوجد نص'); return; }
    downloadBlob(val, 'ترجمة-' + Date.now() + '.txt');
  };
  window.downloadOcrTranslation = function(){
    var val = document.getElementById('ocrTranslatedText').value;
    if(!val){ showToast('لا يوجد نص'); return; }
    downloadBlob(val, 'ترجمة-صورة-' + Date.now() + '.txt');
  };
  function downloadBlob(text, filename){
    var blob = new Blob([text], { type:'text/plain;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click();
    document.body.removeChild(a); URL.revokeObjectURL(url);
    showToast('💾 تم التحميل');
  }
  window.shareText = function(){
    var val = tgtText.value;
    if(!val){ showToast('لا يوجد نص'); return; }
    if(navigator.share){ navigator.share({ title:'ترجمة من المترجم الذكي', text:val }).catch(function(){}); }
    else { copyText('tgtText'); showToast('تم النسخ'); }
  };

  // ============ OCR ============
  var ocrZone = document.getElementById('ocrZone');
  var cameraArea = document.getElementById('cameraArea');
  var previewArea = document.getElementById('previewArea');
  var cameraStream = document.getElementById('cameraStream');
  var previewImg = document.getElementById('previewImg');
  var fileInput = document.getElementById('fileInput');
  var cameraInput = document.getElementById('cameraInput');
  var ocrStatus = document.getElementById('ocrStatus');
  var ocrProgress = document.getElementById('ocrProgress');
  var ocrProgressInner = document.getElementById('ocrProgressInner');
  var ocrExtractedText = document.getElementById('ocrExtractedText');
  var ocrTranslatedText = document.getElementById('ocrTranslatedText');
  var ocrSrcLang = document.getElementById('ocrSrcLang');
  var ocrTgtLang = document.getElementById('ocrTgtLang');
  var currentStream = null;
  var currentImageFile = null;

  ocrExtractedText.addEventListener('input', function(){ updateCount(ocrExtractedText, 'ocrSrcCount'); });
  ocrTranslatedText.addEventListener('input', function(){ updateCount(ocrTranslatedText, 'ocrTgtCount'); });

  document.getElementById('openCameraBtn').addEventListener('click', function(){
    if(navigator.mediaDevices && navigator.mediaDevices.getUserMedia){
      navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } } })
        .then(function(stream){
          currentStream = stream;
          cameraStream.srcObject = stream;
          cameraArea.classList.add('open');
          ocrZone.style.display = 'none';
        }).catch(function(){ cameraInput.click(); });
    } else { cameraInput.click(); }
  });
  document.getElementById('closeCameraBtn').addEventListener('click', function(){
    if(currentStream){ currentStream.getTracks().forEach(function(t){ t.stop(); }); currentStream = null; }
    cameraArea.classList.remove('open'); ocrZone.style.display = 'block';
  });
  document.getElementById('captureBtn').addEventListener('click', function(){
    var canvas = document.createElement('canvas');
    canvas.width = cameraStream.videoWidth; canvas.height = cameraStream.videoHeight;
    canvas.getContext('2d').drawImage(cameraStream, 0, 0);
    canvas.toBlob(function(blob){
      showPreview(blob);
      if(currentStream){ currentStream.getTracks().forEach(function(t){ t.stop(); }); currentStream = null; }
      cameraArea.classList.remove('open'); ocrZone.style.display = 'none';
    }, 'image/jpeg', 0.95);
  });
  document.getElementById('uploadBtn').addEventListener('click', function(){ fileInput.click(); });
  fileInput.addEventListener('change', function(e){ if(e.target.files[0]) showPreview(e.target.files[0]); });
  cameraInput.addEventListener('change', function(e){ if(e.target.files[0]) showPreview(e.target.files[0]); });

  function showPreview(fileOrBlob){
    currentImageFile = fileOrBlob;
    previewImg.src = URL.createObjectURL(fileOrBlob);
    previewArea.classList.add('open'); ocrZone.style.display = 'none';
    ocrStatus.textContent = ''; ocrExtractedText.value = ''; ocrTranslatedText.value = '';
    updateCount(ocrExtractedText, 'ocrSrcCount'); updateCount(ocrTranslatedText, 'ocrTgtCount');
  }
  document.getElementById('resetOcrBtn').addEventListener('click', function(){
    currentImageFile = null; previewImg.src = '';
    previewArea.classList.remove('open'); ocrZone.style.display = 'block';
    ocrStatus.textContent = ''; ocrExtractedText.value = ''; ocrTranslatedText.value = '';
    ocrProgress.classList.remove('open'); ocrProgressInner.style.width = '0%';
  });

  document.getElementById('extractBtn').addEventListener('click', function(){
    if(!currentImageFile){ showToast('⚠️ لا توجد صورة'); return; }
    if(typeof Tesseract === 'undefined'){ ocrStatus.textContent = '❌ فشل تحميل مكتبة OCR'; return; }
    var srcOcrLang = ocrSrcLang.value;
    var tgtLangCode = ocrTgtLang.value;
    ocrStatus.textContent = '⏳ جاري استخراج النص...';
    ocrProgress.classList.add('open'); ocrProgressInner.style.width = '10%';
    Tesseract.recognize(currentImageFile, srcOcrLang, {
      logger: function(m){
        if(m.status === 'recognizing text'){
          var p = Math.round((m.progress || 0) * 100);
          ocrProgressInner.style.width = p + '%';
          ocrStatus.textContent = '⏳ استخراج... ' + p + '%';
        }
      }
    }).then(function(result){
      var extracted = (result.data && result.data.text) ? result.data.text.trim() : '';
      ocrProgressInner.style.width = '100%';
      if(!extracted){ ocrStatus.textContent = '⚠️ لم يُعثر على نص'; setTimeout(function(){ ocrProgress.classList.remove('open'); }, 800); return; }
      ocrExtractedText.value = extracted; updateCount(ocrExtractedText, 'ocrSrcCount');
      ocrStatus.textContent = '⏳ جاري الترجمة...';
      var srcLangCode = ocrToSpeechMap[srcOcrLang] || 'en';
      translate(extracted, srcLangCode, tgtLangCode).then(function(translated){
        ocrTranslatedText.value = translated; updateCount(ocrTranslatedText, 'ocrTgtCount');
        ocrStatus.textContent = '✅ تم بنجاح';
        saveHistory(srcLangCode, tgtLangCode, extracted, translated);
        var s = getStats(); s.translations++; saveStats(s); addPoints(2);
        setTimeout(function(){ ocrProgress.classList.remove('open'); }, 800);
      }).catch(function(){ ocrStatus.textContent = '⚠️ فشلت الترجمة'; setTimeout(function(){ ocrProgress.classList.remove('open'); }, 800); });
    }).catch(function(err){ ocrStatus.textContent = '❌ ' + (err.message || 'خطأ'); ocrProgress.classList.remove('open'); });
  });

  ocrZone.addEventListener('dragover', function(e){ e.preventDefault(); ocrZone.classList.add('dragover'); });
  ocrZone.addEventListener('dragleave', function(){ ocrZone.classList.remove('dragover'); });
  ocrZone.addEventListener('drop', function(e){
    e.preventDefault(); ocrZone.classList.remove('dragover');
    if(e.dataTransfer.files[0]){
      var f = e.dataTransfer.files[0];
      if(f.type.indexOf('image') === 0) showPreview(f); else showToast('⚠️ الملف ليس صورة');
    }
  });

  // ============ FLASHCARDS ============
  var flashcards = [];
  try{ flashcards = JSON.parse(localStorage.getItem('flashcards') || '[]'); }catch(e){ flashcards = []; }
  var fcIndex = 0;
  var flashcard = document.getElementById('flashcard');
  var fcFrontText = document.getElementById('fcFrontText');
  var fcBackText = document.getElementById('fcBackText');
  var fcCounter = document.getElementById('fcCounter');
  var fcList = document.getElementById('fcList');
  var fcListBox = document.getElementById('fcListBox');

  function saveFlashcards(){ localStorage.setItem('flashcards', JSON.stringify(flashcards)); }
  function renderFlashcard(){
    flashcard.classList.remove('flipped');
    if(flashcards.length === 0){
      fcFrontText.textContent = 'مرحباً بك'; fcBackText.textContent = 'Welcome';
      fcCounter.textContent = '0 / 0'; fcListBox.style.display = 'none'; return;
    }
    var card = flashcards[fcIndex];
    fcFrontText.textContent = card.src; fcBackText.textContent = card.tgt;
    fcCounter.textContent = (fcIndex + 1) + ' / ' + flashcards.length;
    renderFcList();
  }
  function renderFcList(){
    if(flashcards.length === 0){ fcListBox.style.display = 'none'; return; }
    fcListBox.style.display = 'block';
    fcList.innerHTML = flashcards.map(function(c){
      return '<div class="history-item"><span class="h-src">' + c.srcLang + ' → ' + c.tgtLang + '</span><span class="h-text">' + c.src + ' = ' + c.tgt + '</span></div>';
    }).join('');
  }
  flashcard.addEventListener('click', function(){ flashcard.classList.toggle('flipped'); });
  flashcard.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); flashcard.classList.toggle('flipped'); } });
  document.getElementById('fcNextBtn').addEventListener('click', function(){ if(!flashcards.length) return; fcIndex = (fcIndex + 1) % flashcards.length; renderFlashcard(); });
  document.getElementById('fcPrevBtn').addEventListener('click', function(){ if(!flashcards.length) return; fcIndex = (fcIndex - 1 + flashcards.length) % flashcards.length; renderFlashcard(); });
  document.getElementById('fcSpeakBtn').addEventListener('click', function(){
    if(!flashcards.length) return;
    var card = flashcards[fcIndex];
    var isFlipped = flashcard.classList.contains('flipped');
    var textToSpeak = isFlipped ? card.tgt : card.src;
    var langCode = isFlipped ? card.tgtLang : card.srcLang;
    if(!window.speechSynthesis){ showToast('لا يوجد دعم'); return; }
    var utter = new SpeechSynthesisUtterance(textToSpeak);
    utter.lang = speechMap[langCode] || 'en-US';
    var auto = findVoiceForLang(langCode);
    if(auto){ utter.voice = auto; utter.lang = auto.lang; }
    window.speechSynthesis.cancel();
    setTimeout(function(){ window.speechSynthesis.speak(utter); showToast('🔊 ' + textToSpeak); }, 100);
  });

  // SHARE FLASHCARD AS IMAGE
  document.getElementById('fcShareBtn').addEventListener('click', function(){
    if(!flashcards.length){ showToast('لا توجد بطاقات'); return; }
    var card = flashcards[fcIndex];
    var canvas = document.createElement('canvas');
    canvas.width = 800; canvas.height = 500;
    var ctx = canvas.getContext('2d');
    var grad = ctx.createLinearGradient(0, 0, 800, 500);
    grad.addColorStop(0, '#8A9A7E');
    grad.addColorStop(1, '#5F6F52');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 800, 500);
    ctx.fillStyle = 'rgba(255,255,255,0.95)';
    ctx.beginPath();
    var r = 24;
    ctx.moveTo(r+30, 60);
    ctx.lineTo(800-30-r, 60);
    ctx.quadraticCurveTo(800-30, 60, 800-30, 60+r);
    ctx.lineTo(800-30, 500-60-r);
    ctx.quadraticCurveTo(800-30, 500-60, 800-30-r, 500-60);
    ctx.lineTo(r+30, 500-60);
    ctx.quadraticCurveTo(30, 500-60, 30, 500-60-r);
    ctx.lineTo(30, 60+r);
    ctx.quadraticCurveTo(30, 60, r+30, 60);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#5F6F52';
    ctx.font = 'bold 20px Tajawal, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('🤖 المترجم الذكي', 400, 110);
    ctx.fillStyle = '#3A3F35';
    ctx.font = 'bold 42px Tajawal, sans-serif';
    ctx.fillText(card.src, 400, 240);
    ctx.strokeStyle = '#B9C4AE';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(200, 290); ctx.lineTo(600, 290); ctx.stroke();
    ctx.fillStyle = '#8A9A7E';
    ctx.font = 'bold 36px Tajawal, sans-serif';
    ctx.fillText(card.tgt, 400, 360);
    ctx.fillStyle = '#6E7768';
    ctx.font = '14px Tajawal, sans-serif';
    ctx.fillText('تعلم اللغات مجاناً على المترجم الذكي', 400, 440);
    canvas.toBlob(function(blob){
      if(navigator.share && navigator.canShare && navigator.canShare({files:[new File([blob], 'flashcard.png', {type:'image/png'})]})){
        navigator.share({ files:[new File([blob], 'flashcard.png', {type:'image/png'})], title:'بطاقة تعليمية' });
      } else {
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url; a.download = 'flashcard-' + Date.now() + '.png';
        document.body.appendChild(a); a.click();
        document.body.removeChild(a); URL.revokeObjectURL(url);
        showToast('📤 تم تحميل الصورة');
      }
    }, 'image/png');
  });

  document.getElementById('addFlashcardBtn').addEventListener('click', function(){
    var word = document.getElementById('fcWord').value.trim();
    var srcL = document.getElementById('fcSrcLang').value;
    var tgtL = document.getElementById('fcTgtLang').value;
    if(!word){ showToast('⚠️ اكتب كلمة'); return; }
    if(srcL === tgtL){ showToast('⚠️ نفس اللغة'); return; }
    var btn = this;
    btn.disabled = true; btn.textContent = '⏳...';
    translate(word, srcL, tgtL).then(function(result){
      flashcards.push({ src:word, tgt:result, srcLang:srcL, tgtLang:tgtL });
      saveFlashcards(); fcIndex = flashcards.length - 1; renderFlashcard();
      document.getElementById('fcWord').value = '';
      btn.disabled = false; btn.textContent = '➕ إضافة';
      var s = getStats(); s.wordsLearned++; saveStats(s); addPoints(5);
      showToast('✅ تمت الإضافة');
    }).catch(function(){ btn.disabled = false; btn.textContent = '➕ إضافة'; showToast('❌ فشلت'); });
  });

  document.getElementById('clearFlashcardsBtn').addEventListener('click', function(){
    if(!confirm('مسح كل البطاقات؟')) return;
    flashcards = []; fcIndex = 0; saveFlashcards(); renderFlashcard(); showToast('تم المسح');
  });

  // EXPORT / IMPORT
  window.exportFlashcards = function(){
    if(!flashcards.length){ showToast('لا توجد بطاقات'); return; }
    var data = JSON.stringify(flashcards, null, 2);
    downloadBlob(data, 'flashcards-' + Date.now() + '.json');
  };
  document.getElementById('importFile').addEventListener('change', function(e){
    var file = e.target.files[0];
    if(!file) return;
    var reader = new FileReader();
    reader.onload = function(ev){
      try{
        var imported = JSON.parse(ev.target.result);
        if(!Array.isArray(imported)) throw new Error('invalid');
        flashcards = flashcards.concat(imported);
        saveFlashcards(); renderFlashcard();
        showToast('✅ تم استيراد ' + imported.length + ' بطاقة');
      }catch(err){ showToast('❌ ملف غير صالح'); }
    };
    reader.readAsText(file);
    e.target.value = '';
  });

  // ============ QUIZ ============
  var quizModal = document.getElementById('quizModal');
  var resultModal = document.getElementById('resultModal');
  var quizBody = document.getElementById('quizBody');
  var quizFooter = document.getElementById('quizFooter');
  var quizProgressFill = document.getElementById('quizProgressFill');
  var quizProgressText = document.getElementById('quizProgressText');
  var quizQuestions = [], quizCurrentIndex = 0, quizCorrectCount = 0, quizWrongCount = 0, quizAnswered = false;
  var quizDifficulty = 'easy';

  document.querySelectorAll('.diff-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      document.querySelectorAll('.diff-btn').forEach(function(b){ b.classList.remove('active'); });
      this.classList.add('active');
      quizDifficulty = this.getAttribute('data-diff');
    });
  });

  function shuffle(arr){
    var a = arr.slice();
    for(var i = a.length - 1; i > 0; i--){
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function buildQuestions(){
    if(flashcards.length < 2){ showToast('⚠️ تحتاج بطاقتين'); return []; }
    var count = quizDifficulty === 'easy' ? 5 : (quizDifficulty === 'medium' ? 8 : 12);
    var pool = shuffle(flashcards).slice(0, Math.min(count, flashcards.length));
    return pool.map(function(card, idx){
      var type = 'multiple';
      if(quizDifficulty !== 'easy'){
        if(idx % 3 === 1) type = 'input';
        else if(idx % 3 === 2) type = 'truefalse';
      }
      var q = { type:type, prompt:'ما ترجمة هذه الكلمة؟', word:card.src, answer:card.tgt, srcLang:card.srcLang, tgtLang:card.tgtLang };
      if(type === 'multiple'){
        var wrongPool = flashcards.filter(function(c){ return c.tgt !== card.tgt; });
        var wrongs = shuffle(wrongPool).slice(0, 3).map(function(c){ return c.tgt; });
        q.options = shuffle([card.tgt].concat(wrongs));
      } else if(type === 'truefalse'){
        var isTrue = Math.random() > 0.5;
        if(isTrue){ q.shownAnswer = card.tgt; q.answerBool = true; }
        else {
          var others = flashcards.filter(function(c){ return c.tgt !== card.tgt; });
          q.shownAnswer = others.length ? others[Math.floor(Math.random() * others.length)].tgt : 'خاطئة';
          q.answerBool = false;
        }
      }
      return q;
    });
  }

  function startQuiz(){
    if(flashcards.length < 2){ showToast('⚠️ أضف بطاقتين'); return; }
    quizQuestions = buildQuestions();
    if(!quizQuestions.length) return;
    quizCurrentIndex = 0; quizCorrectCount = 0; quizWrongCount = 0;
    quizModal.classList.add('open');
    renderQuestion();
  }

  function renderQuestion(){
    quizAnswered = false;
    var q = quizQuestions[quizCurrentIndex];
    var total = quizQuestions.length;
    quizProgressFill.style.width = ((quizCurrentIndex) / total * 100) + '%';
    quizProgressText.textContent = (quizCurrentIndex + 1) + ' / ' + total;
    var html = '<div class="quiz-question">' + q.prompt + '</div><div class="quiz-word">' + q.word + '</div>';
    if(q.type === 'multiple'){
      html += '<div class="quiz-options">';
      q.options.forEach(function(opt){ html += '<button class="quiz-option" data-answer="' + escapeHtml(opt) + '" type="button">' + escapeHtml(opt) + '</button>'; });
      html += '</div>';
    } else if(q.type === 'input'){
      html += '<input class="quiz-input" id="quizInput" placeholder="اكتب الترجمة..." type="text"/>';
    } else if(q.type === 'truefalse'){
      html += '<div class="quiz-question">هل هذه الترجمة صحيحة؟</div>';
      html += '<div class="quiz-word" style="background:var(--sage);color:var(--white);">' + escapeHtml(q.shownAnswer) + '</div>';
      html += '<div class="quiz-options"><button class="quiz-option" data-tf="true" type="button">✅ صحيح</button><button class="quiz-option" data-tf="false" type="button">❌ خطأ</button></div>';
    }
    quizBody.innerHTML = html; quizFooter.innerHTML = '';
    if(q.type === 'multiple'){
      quizBody.querySelectorAll('.quiz-option').forEach(function(btn){
        btn.addEventListener('click', function(){ checkAnswer(this.getAttribute('data-answer') === q.answer, this, q.answer); });
      });
    } else if(q.type === 'truefalse'){
      quizBody.querySelectorAll('.quiz-option').forEach(function(btn){
        btn.addEventListener('click', function(){ checkAnswer((this.getAttribute('data-tf') === 'true') === q.answerBool, this, q.answerBool ? 'صحيح' : 'خطأ'); });
      });
    } else if(q.type === 'input'){
      var input = document.getElementById('quizInput');
      input.focus();
      input.addEventListener('keypress', function(e){ if(e.key === 'Enter') submitInput(); });
      quizFooter.innerHTML = '<button class="btn-main" id="quizSubmitBtn" type="button" style="padding:12px 40px;">تحقق</button>';
      document.getElementById('quizSubmitBtn').addEventListener('click', submitInput);
      function submitInput(){
        if(quizAnswered) return;
        var val = input.value.trim();
        if(!val){ showToast('⚠️ اكتب إجابة'); return; }
        checkAnswer(normalizeArabic(val) === normalizeArabic(q.answer), null, q.answer);
        input.disabled = true;
      }
    }
  }

  function escapeHtml(s){ return String(s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
  function normalizeArabic(s){ return String(s).trim().replace(/[إأآا]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/[\u064B-\u0652]/g, '').replace(/\s+/g, ' '); }

  function checkAnswer(isCorrect, btnEl, correctAnswer){
    if(quizAnswered) return;
    quizAnswered = true;
    var q = quizQuestions[quizCurrentIndex];
    quizBody.querySelectorAll('.quiz-option').forEach(function(b){
      b.disabled = true;
      var bAns = b.getAttribute('data-answer');
      var bTf = b.getAttribute('data-tf');
      if(bAns !== null){ if(bAns === correctAnswer) b.classList.add('correct'); else if(b === btnEl) b.classList.add('wrong'); }
      else if(bTf !== null){ if((bTf === 'true') === q.answerBool) b.classList.add('correct'); else if(b === btnEl) b.classList.add('wrong'); }
    });
    var input = document.getElementById('quizInput');
    if(input) input.disabled = true;
    if(isCorrect) quizCorrectCount++; else quizWrongCount++;
    var fb = document.createElement('div');
    fb.className = 'quiz-feedback ' + (isCorrect ? 'correct' : 'wrong');
    fb.textContent = isCorrect ? '✅ صحيح!' : '❌ الإجابة: ' + correctAnswer;
    quizBody.appendChild(fb);
    quizFooter.innerHTML = '';
    var nextBtn = document.createElement('button');
    nextBtn.className = 'btn-main'; nextBtn.type = 'button';
    nextBtn.style.padding = '12px 40px';
    nextBtn.textContent = (quizCurrentIndex === quizQuestions.length - 1) ? '🏁 النتيجة' : 'التالي ➡️';
    nextBtn.addEventListener('click', nextQuestion);
    quizFooter.appendChild(nextBtn);
  }

  function nextQuestion(){
    quizCurrentIndex++;
    if(quizCurrentIndex >= quizQuestions.length){ showResult(); return; }
    renderQuestion();
  }

  function showResult(){
    quizModal.classList.remove('open');
    var total = quizQuestions.length;
    var percent = Math.round((quizCorrectCount / total) * 100);
    var s = getStats();
    s.quizzesTaken++;
    if(percent > s.bestScore) s.bestScore = percent;
    s.totalPoints += percent;
    saveStats(s);
    checkAchievements();
    document.getElementById('statCorrect').textContent = quizCorrectCount;
    document.getElementById('statWrong').textContent = quizWrongCount;
    document.getElementById('statBest').textContent = s.bestScore + '%';
    document.getElementById('scoreNumber').textContent = percent;
    document.getElementById('scoreCircle').style.setProperty('--score-deg', (percent / 100 * 360) + 'deg');
    var icon = '🎉', title = 'أحسنت!';
    if(percent < 50){ icon = '💪'; title = 'حاول مرة أخرى'; }
    else if(percent < 80){ icon = '👍'; title = 'جيد جداً'; }
    else if(percent < 100){ icon = '🌟'; title = 'ممتاز!'; }
    else { icon = '🏆'; title = 'مثالي!'; }
    document.getElementById('resultIcon').textContent = icon;
    document.getElementById('resultTitle').textContent = title;
    document.getElementById('resultSubtitle').textContent = 'أجبت على ' + total + ' سؤال';
    resultModal.classList.add('open');
  }

  document.getElementById('startQuizBtn').addEventListener('click', startQuiz);
  document.getElementById('quizCloseBtn').addEventListener('click', function(){ quizModal.classList.remove('open'); });
  document.getElementById('retryQuizBtn').addEventListener('click', function(){ resultModal.classList.remove('open'); startQuiz(); });
  document.getElementById('closeResultBtn').addEventListener('click', function(){ resultModal.classList.remove('open'); });
  quizModal.addEventListener('click', function(e){ if(e.target === quizModal) quizModal.classList.remove('open'); });
  resultModal.addEventListener('click', function(e){ if(e.target === resultModal) resultModal.classList.remove('open'); });

  // ============ DICTIONARY ============
  var dictExamples = {
    'hello': 'Hello, how are you today?',
    'book': 'I read a book every night.',
    'school': 'My school is near my house.',
    'teacher': 'The teacher explained the lesson.',
    'student': 'She is a hardworking student.',
    'water': 'Drink plenty of water daily.',
    'friend': 'He is my best friend.',
    'love': 'I love learning languages.',
    'time': 'Time is precious.',
    'work': 'I go to work every morning.',
    'house': 'They bought a new house.',
    'city': 'Riyadh is a beautiful city.'
  };
  function getExample(word){
    var w = word.toLowerCase().trim();
    return dictExamples[w] || ('Example with "' + word + '": This is a sample sentence using the word.');
  }
  document.getElementById('dictSearchBtn').addEventListener('click', function(){
    var word = document.getElementById('dictWord').value.trim();
    var src = document.getElementById('dictSrc').value;
    var tgt = document.getElementById('dictTgt').value;
    var status = document.getElementById('dictStatus');
    var area = document.getElementById('dictResultArea');
    if(!word){ status.textContent = '⚠️ اكتب كلمة'; return; }
    status.textContent = '⏳ جاري البحث...';
    area.innerHTML = '';
    translate(word, src, tgt).then(function(result){
      var example = getExample(word);
      var exampleT = '';
      translate(example, 'en', tgt).then(function(exT){
        exampleT = exT;
        area.innerHTML = '<div class="dict-result">' +
          '<div class="dict-word">📖 ' + escapeHtml(word) + '</div>' +
          '<div class="dict-meaning"><strong>الترجمة:</strong> ' + escapeHtml(result) + '</div>' +
          '<div class="dict-example"><span class="dict-example-label">📝 مثال بالإنجليزية:</span>' + escapeHtml(example) + '</div>' +
          (exampleT ? '<div class="dict-example"><span class="dict-example-label">🌐 ترجمة المثال:</span>' + escapeHtml(exampleT) + '</div>' : '') +
          '<div style="margin-top:12px;text-align:center;"><button class="btn-speak" onclick="speakWord(&quot;' + escapeHtml(word) + '&quot;,&quot;' + src + '&quot;)" type="button">🔊 نطق الكلمة</button></div>' +
          '</div>';
        status.textContent = '✅ تم البحث';
      }).catch(function(){
        area.innerHTML = '<div class="dict-result"><div class="dict-word">📖 ' + escapeHtml(word) + '</div><div class="dict-meaning"><strong>الترجمة:</strong> ' + escapeHtml(result) + '</div><div class="dict-example"><span class="dict-example-label">📝 مثال:</span>' + escapeHtml(example) + '</div></div>';
        status.textContent = '✅ تم البحث';
      });
    }).catch(function(){ status.textContent = '❌ فشل البحث'; });
  });
  window.speakWord = function(word, lang){
    if(!window.speechSynthesis) return;
    var utter = new SpeechSynthesisUtterance(word);
    utter.lang = speechMap[lang] || 'en-US';
    var auto = findVoiceForLang(lang);
    if(auto){ utter.voice = auto; utter.lang = auto.lang; }
    window.speechSynthesis.cancel();
    setTimeout(function(){ window.speechSynthesis.speak(utter); }, 100);
  };

  // ============ DAILY WORD ============
  var dailyWords = [
    {ar:'مرحبا', en:'Hello'}, {ar:'شكرا', en:'Thank you'}, {ar:'كتاب', en:'Book'},
    {ar:'مدرسة', en:'School'}, {ar:'معلم', en:'Teacher'}, {ar:'طالب', en:'Student'},
    {ar:'ماء', en:'Water'}, {ar:'صديق', en:'Friend'}, {ar:'حب', en:'Love'},
    {ar:'وقت', en:'Time'}, {ar:'عمل', en:'Work'}, {ar:'بيت', en:'House'},
    {ar:'مدينة', en:'City'}, {ar:'طعام', en:'Food'}, {ar:'سفر', en:'Travel'},
    {ar:'كتابة', en:'Writing'}, {ar:'قراءة', en:'Reading'}, {ar:'لغة', en:'Language'},
    {ar:'علم', en:'Science'}, {ar:'فن', en:'Art'}, {ar:'موسيقى', en:'Music'},
    {ar:'رياضة', en:'Sport'}, {ar:'صحة', en:'Health'}, {ar:'عائلة', en:'Family'},
    {ar:'طبيعة', en:'Nature'}, {ar:'شمس', en:'Sun'}, {ar:'قمر', en:'Moon'},
    {ar:'نجم', en:'Star'}, {ar:'بحر', en:'Sea'}, {ar:'جبل', en:'Mountain'}
  ];
  function loadDailyWord(){
    var box = document.getElementById('dailyWordBox');
    if(!box) return;
    var dayIndex = Math.floor(Date.now() / 86400000) % dailyWords.length;
    var w = dailyWords[dayIndex];
    box.innerHTML = '<div class="dict-word">📅 كلمة اليوم: ' + w.ar + '</div>' +
      '<div class="dict-meaning"><strong>بالإنجليزية:</strong> ' + w.en + '</div>' +
      '<div style="text-align:center;margin-top:12px;">' +
      '<button class="btn-speak" onclick="speakWord(&quot;' + w.en + '&quot;,&quot;en&quot;)" type="button">🔊 نطق</button>' +
      '</div>';
  }

  // ============ INIT ============
  renderFlashcard();
  renderHistory();
  renderStats();

})();
